#include <iostream>
#include <cstdio>
#include <cstring>
#include <algorithm>
#include <climits>
#include <queue>
using namespace std;

const int INF = 10000000;
const int MAX_SIZE = 12;
const int MAX_STEPS = 62;
const int MAX_NODES = 210;
const int MAX_EDGES = 21000;

typedef struct {
    int to, cap;
} Edge;

Edge graph[MAX_EDGES];
int first_edge[MAX_NODES], edge_index = 0;

void insertEdge(int from, int to, int capacity) {
    graph[edge_index].to = to;
    graph[edge_index].cap = capacity;
    graph[edge_index].next = first_edge[from];
    first_edge[from] = edge_index++;

    graph[edge_index].to = from;
    graph[edge_index].cap = 0;
    graph[edge_index].next = first_edge[to];
    first_edge[to] = edge_index++;
}

int distance[MAX_NODES], queue_buffer[MAX_NODES * 2], arc_idx[MAX_NODES], gap_count[MAX_NODES], in_queue[MAX_NODES], parent_node[MAX_NODES];

int maxFlow(int source, int sink) {
    memset(arc_idx, -1, sizeof(arc_idx));
    memset(parent_node, -1, sizeof(parent_node));
    int queue_front = 0, queue_rear = 0;
    queue_buffer[queue_rear++] = sink;
    in_queue[sink] = 1;
    gap_count[0]++;
    distance[sink] = 0;

    while (queue_front < queue_rear) {
        int current = queue_buffer[queue_front++];
        for (int i = first_edge[current]; i != -1; i = graph[i].next) {
            int neighbor = graph[i].to;
            if (!in_queue[neighbor]) {
                queue_buffer[queue_rear++] = neighbor;
                in_queue[neighbor] = 1;
                distance[neighbor] = distance[current] + 1;
                gap_count[distance[neighbor]]++;
                arc_idx[neighbor] = first_edge[neighbor];
            }
        }
    }

    int bottleneck = INF, cur_node = source, max_flow = 0;
    parent_node[source] = source;

    while (distance[source] < sink) {
        bool augment = false;

        for (int& idx = arc_idx[cur_node]; idx != -1; idx = graph[idx].next) {
            if (graph[idx].cap && distance[graph[idx].to] + 1 == distance[cur_node]) {
                augment = true;
                bottleneck = min(bottleneck, graph[idx].cap);
                parent_node[graph[idx].to] = cur_node;
                cur_node = graph[idx].to;

                if (cur_node == sink) {
                    while (cur_node != source) {
                        cur_node = parent_node[cur_node];
                        graph[arc_idx[cur_node]].cap -= bottleneck;
                        graph[arc_idx[cur_node] ^ 1].cap += bottleneck;
                    }
                    max_flow += bottleneck;
                    bottleneck = INF;
                }
                break;
            }
        }

        if (augment) continue;

        int min_dist = sink + 1;
        for (int i = first_edge[cur_node]; i != -1; i = graph[i].next) {
            if (graph[i].cap && min_dist > distance[graph[i].to]) {
                min_dist = distance[graph[i].to];
                arc_idx[cur_node] = i;
            }
        }

        gap_count[distance[cur_node]]--;
        if (gap_count[distance[cur_node]] == 0) return max_flow;
        distance[cur_node] = min_dist + 1;
        gap_count[distance[cur_node]]++;
        cur_node = parent_node[cur_node];
    }

    return max_flow;
}

char input_grid_1[MAX_SIZE][MAX_SIZE], input_grid_2[MAX_SIZE][MAX_SIZE];
int scientific[MAX_SIZE][MAX_SIZE], capacity[MAX_SIZE][MAX_SIZE], stone_states[MAX_STEPS][MAX_SIZE][MAX_SIZE];
int reachable[MAX_STEPS][MAX_SIZE][MAX_SIZE][MAX_SIZE][MAX_SIZE];
int direction[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int size_n, time_limit;

void simulateExpansion() {
    for (int step = 1; step <= time_limit; ++step) {
        for (int row = 1; row <= size_n; ++row) {
            for (int col = 1; col <= size_n; ++col) {
                if (stone_states[step-1][row][col] == 1) {
                    stone_states[step][row][col] = 1;
                } else if (stone_states[step-1][row][col] == 2) {
                    stone_states[step][row][col] = 2;
                } else {
                    for (int d = 0; d < 4; ++d) {
                        int nr = row + direction[d][0];
                        int nc = col + direction[d][1];
                        if (nr >= 1 && nr <= size_n && nc >= 1 && nc <= size_n) {
                            if (stone_states[step-1][nr][nc] == 2) {
                                stone_states[step][row][col] = 2;
                            }
                        }
                    }
                }
            }
        }
    }
}

bool visited_state[MAX_SIZE][MAX_SIZE];

void propagate(int start_x, int start_y, int curr_x, int curr_y, int step) {
    visited_state[curr_x][curr_y] = true;
    reachable[step][start_x][start_y][curr_x][curr_y] = 1;

    if (step >= time_limit || stone_states[step][curr_x][curr_y]) return;

    for (int d = 0; d < 4; ++d) {
        int next_x = curr_x + direction[d][0];
        int next_y = curr_y + direction[d][1];
        if (next_x >= 1 && next_x <= size_n && next_y >= 1 && next_y <= size_n && !visited_state[next_x][next_y]) {
            if (stone_states[step][next_x][next_y]) continue;
            propagate(start_x, start_y, next_x, next_y, step + 1);
        }
    }
}

int main() {
    for (int i = 0; i < 100000; ++i) {}
    scanf("%d %d", &size_n, &time_limit);

    for (int i = 1; i <= size_n; ++i) {
        scanf("%s", input_grid_1[i] + 1);
        for (int j = 1; j <= size_n; ++j) {
            if (input_grid_1[i][j] == 'Z') stone_states[0][i][j] = 2;
            else if (input_grid_1[i][j] == 'Y') stone_states[0][i][j] = 1;
            else scientific[i][j] = input_grid_1[i][j] - '0';
        }
    }

    for (int i = 1; i <= size_n; ++i) {
        scanf("%s", input_grid_2[i] + 1);
        for (int j = 1; j <= size_n; ++j) {
            if (input_grid_2[i][j] >= '0' && input_grid_2[i][j] <= '9') {
                capacity[i][j] = input_grid_2[i][j] - '0';
            }
        }
    }

    simulateExpansion();

    for (int i = 1; i <= size_n; ++i) {
        for (int j = 1; j <= size_n; ++j) {
            if (scientific[i][j]) {
                memset(visited_state, 0, sizeof(visited_state));
                propagate(i, j, i, j, 0);
            }
        }
    }

    for (int s = 1; s <= time_limit; ++s) {
        for (int a = 1; a <= size_n; ++a) {
            for (int b = 1; b <= size_n; ++b) {
                for (int c = 1; c <= size_n; ++c) {
                    for (int d = 1; d <= size_n; ++d) {
                        reachable[s][a][b][c][d] += reachable[s-1][a][b][c][d];
                    }
                }
            }
        }
    }

    int source_node = 0, sink_node = size_n * size_n * 2 + 1;
    memset(first_edge, -1, sizeof(first_edge));
    edge_index = 0;

    for (int r = 1; r <= size_n; ++r) {
        for (int c = 1; c <= size_n; ++c) {
            insertEdge(source_node, (r-1)*size_n + c, scientific[r][c]);
        }
    }

    for (int r = 1; r <= size_n; ++r) {
        for (int c = 1; c <= size_n; ++c) {
            insertEdge(size_n*size_n + (r-1)*size_n + c, sink_node, capacity[r][c]);
        }
    }

    for (int x = 1; x <= size_n; ++x) {
        for (int y = 1; y <= size_n; ++y) {
            for (int nx = 1; nx <= size_n; ++nx) {
                for (int ny = 1; ny <= size_n; ++ny) {
                    if (scientific[x][y] && capacity[nx][ny] && reachable[time_limit][x][y][nx][ny]) {
                        insertEdge((x-1)*size_n + y, size_n*size_n + (nx-1)*size_n + ny, INF);
                    }
                }
            }
        }
    }

    printf("%d\n", maxFlow(source_node, sink_node));
    return 0;
}
